mapper.update:
UPDATE medical_records SET diagnosis = #{record.diagnosis}, treatment_plan = #{record.treatmentPlan},
    medical_advice = #{record.medicalAdvice}, record_status = #{record.recordStatus}, version = version + 1,
    finalized_at = CASE WHEN #{record.recordStatus} = 'FINAL' THEN CURRENT_TIMESTAMP ELSE NULL END,
    updated_at = CURRENT_TIMESTAMP
WHERE medical_record_id = #{record.medicalRecordId} AND doctor_id = #{record.doctorId}
  AND record_status = 'DRAFT' AND version = #{expectedVersion}

mapper.select:
SELECT mr.* FROM medical_records mr
INNER JOIN appointments a ON a.appointment_id = mr.appointment_id
WHERE mr.appointment_id = #{appointmentId} AND a.doctor_id = #{doctorId}
